package ua.stetsenkoinna.graphpresentation.training;

import java.util.*;

/** Only settings enter from clients; execution evidence is generated by the application. */
public record SimulationPlan(List<Double> horizons, double samplingInterval, String skipReason, List<Map<String, Object>> interactiveRuns) {
    public SimulationPlan {
        horizons = horizons == null ? List.of() : List.copyOf(horizons);
        skipReason = skipReason == null ? "" : skipReason.strip();
        interactiveRuns = interactiveRuns == null ? List.of() : List.copyOf(interactiveRuns);
        if (horizons.isEmpty() && skipReason.isBlank()) throw new IllegalArgumentException("Enable automatic simulation or give a reason for skipping it.");
        if (!horizons.isEmpty() && !skipReason.isEmpty()) throw new IllegalArgumentException("Choose automatic simulation or a skip reason, not both.");
        if (horizons.size() > 8 || horizons.stream().anyMatch(h -> h == null || !Double.isFinite(h) || h <= 0 || h > 1_000_000)) throw new IllegalArgumentException("Use 1-8 simulation horizons above zero and at most 1000000.");
        if (!Double.isFinite(samplingInterval) || samplingInterval <= 0) throw new IllegalArgumentException("Sampling interval must be finite and positive.");
        if (skipReason.length() > 4000 || interactiveRuns.size() > 256) throw new IllegalArgumentException("Review simulation evidence exceeds its limit.");
    }
    public static SimulationPlan defaults() { return new SimulationPlan(List.of(100.0, 1000.0, 10000.0), 1, "", List.of()); }
}
